package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;
public final class FollowerChecks {
 static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static double[] direction(Models.Mat pose){double[] p=pose.point(0,0,0),q=pose.point(0,1,0);return new double[]{q[0]-p[0],q[1]-p[1],q[2]-p[2]};}
 static double difference(double[]a,double[]b){return Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2]);}
 public static void main(String[]args)throws Exception{Assets.Entry pet=new Assets.Entry();double dt=1d/60;Follower.update(pet,0,0,0,0,dt);double x=pet.px,z=pet.pz,heading=pet.yaw;
  for(int frame=0;frame<1200;frame++)require(!Follower.update(pet,0,0,0,frame*3,dt),"Stationary head turn triggers walking");require(pet.px==x&&pet.pz==z&&pet.yaw==heading&&pet.speed==0,"Stationary head turn moves pet");
  boolean moved=false;for(int frame=1;frame<=240;frame++)moved|=Follower.update(pet,frame*2.9/60,0,0,frame*7,dt);require(moved&&pet.px>x+7,"Owner translation does not trigger following");
  for(int frame=0;frame<300;frame++)Follower.update(pet,240*2.9/60,0,0,frame*11,dt);x=pet.px;z=pet.pz;for(int frame=0;frame<600;frame++)require(!Follower.update(pet,240*2.9/60,0,0,frame*17,dt),"Settled pet keeps walking");require(pet.px==x&&pet.pz==z&&pet.speed==0,"Settled pet drifts");
  require(!Follower.update(pet,100,0,100,0,dt)&&Math.hypot(pet.px-100,pet.pz-100)<3,"Teleport catch-up failed");
  Assets.load(Files.readAllBytes(Paths.get(args[0])));int mini=0;for(Assets.Entry e:Assets.entries)if(e.slot.equals("companion")){Models.Model m=Models.load(e);if(!m.mini)continue;Expr.Context c=new Expr.Context();c.time=1;m.activeAnimations=Models.active(m,c,false);require(!m.activeAnimations.contains("walk"),"Idle mini activates walk");Models.Bone leg=m.byName.get(m.duo?m.duoFirst+"left_leg":"left_leg"),head=m.byName.get(m.duo?m.duoFirst+"headtilt":"headtilt");double[] l=direction(Models.pose(m,leg,c,false,new HashMap<String,Models.Mat>(),0,0)),h=direction(Models.pose(m,head,c,false,new HashMap<String,Models.Mat>(),0,0));c.time=4;require(difference(l,direction(Models.pose(m,leg,c,false,new HashMap<String,Models.Mat>(),0,0)))<.001,"Idle legs keep swinging");Models.Mat p=Models.pose(m,head,c,false,new HashMap<String,Models.Mat>(),0,0);double[] front=p.point(0,0,-1),origin=p.point(0,0,0);c.time=1;Models.Mat q=Models.pose(m,head,c,false,new HashMap<String,Models.Mat>(),0,0);double[] old=q.point(0,0,-1),oldOrigin=q.point(0,0,0);require(Math.abs((front[0]-origin[0])-(old[0]-oldOrigin[0]))>.01,"Idle head no longer looks around");mini++;}require(mini==19,"Expected nineteen ground mini variants including duo");System.out.println("PASS stationary turning, translation follow, settled stop without gait/drift, teleport recovery, nineteen calm mini idles with stationary legs and animated head");}
}
